threads.body:
Nested agents get a duplicate agent span when the outer agent sets `metadata["agent_name"]` - the inner agent's internal nodes still inherit the outer name and open another layer:

```
invoke_agent math_agent        <- root
  execute_tool delegate
    invoke_agent inner
      invoke_agent math_agent  <- spurious
```

The inherited-name check shouldn't be conditional on `declared_agent_name`.

The nested tests don't catch this because they only check names are unique and roots are roots, never the full span set. This one fails on the branch:

```python
def test_nested_agent_emits_no_extra_agent_spans(
    span_exporter, start_instrumentation
) -> None:
    inner = create_agent(
        FakeModel(responses=[AIMessage(content="inner done")]),
        [noop],
        name="inner",
    )

    @tool
    def delegate(config: RunnableConfig) -> str:
        """Delegate to the inner agent."""
        result = inner.invoke({"messages": [("user", "work")]}, config)
        return str(result["messages"][-1].content)

    create_agent(
        FakeModel(
            responses=[
                AIMessage(
                    content="",
                    tool_calls=[
                        {"name": "delegate", "args": {}, "id": "call-1"}
                    ],
                ),
                AIMessage(content="outer done"),
            ]
        ),
        [delegate],
        name="outer",
    ).with_config(metadata={"agent_name": "math_agent"}).invoke(
        {"messages": [("user", "start")]}
    )

    spans = span_exporter.get_finished_spans()
    assert sorted(span.name for span in spans) == [
        "execute_tool delegate",
        "invoke_agent inner",
        "invoke_agent math_agent",
    ]
```

```
E   AssertionError: Left contains one more item: 'invoke_agent math_agent'
```
